qualified_questions.sparql_query:
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ssn: <http://www.w3.org/ns/ssn/>

SELECT ?definition
WHERE {
  ssn:System rdfs:isDefinedBy ?definition
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  geo:sfWithin rdfs:isDefinedBy ?definition
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?type
WHERE {
  :hasVendor rdf:type ?type
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>

SELECT ?definition
WHERE {
  s4bldg:BuildingSpace rdfs:isDefinedBy ?definition
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?definition
WHERE {
  geo:sfContains rdfs:isDefinedBy ?definition
}

PREFIX s4bldg: <https://w3id.org/def/saref4bldg#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?seeAlso ?source
WHERE {
  s4bldg:Building rdfs:seeAlso ?seeAlso ;
                  prov:hadPrimarySource ?source .
}

PREFIX : <http://example.org/ontology#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(?device) AS ?numberOfDevices)
WHERE {
  ?device rdf:type :Device ;
          :softwareVersion ?specificSoftwareVersion ;
          :serialNumber ?particularSerialNumber .
  FILTER(?specificSoftwareVersion = "specific_version"^^xsd:string && ?particularSerialNumber = "particular_serial_number"^^xsd:string)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX : <http://example.org/ontology#>

SELECT (COUNT(?service) AS ?numberOfServices)
WHERE {
  ?service a :Service ;
           :serviceName ?name ;
           :serviceDescription ?description .
  FILTER(?name = "specific name" && ?description = "particular description")
}

SELECT ?type
WHERE {
  :readWrite rdf:type ?type .
  FILTER(?type = owl:DatatypeProperty || ?type = owl:FunctionalProperty)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX org: <http://www.w3.org/ns/org#>
PREFIX : <http://example.org/>

SELECT (COUNT(?partner) AS ?numberOfPartnerships)
WHERE {
  :organizationURI a org:Organization ;
                   :hasPartnershipWith ?partner .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property ?type
WHERE {
  ?property rdf:type owl:ObjectProperty .
  OPTIONAL { ?property rdf:type ?type }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?domain
WHERE {
  rdf:value rdfs:domain ?domain
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
  ?property rdf:type owl:ObjectProperty ;
            rdfs:domain rdfs:Resource ;
            rdfs:range rdfs:Resource .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?inverse
WHERE {
  :involves owl:inverseOf ?inverse .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?property
WHERE {
  ?property rdf:type owl:FunctionalProperty
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?property ?role
WHERE {
  ?property rdf:type owl:ObjectProperty .
  FILTER (?property = :aboutProperty || ?property = :describesEcosystem || ?property = :isNeighbourhoodOf || ?property = :isEcosystemDescribedBy || ?property = :isInvolvedIn || ?property = :involves)
  OPTIONAL {
    ?property rdf:type owl:FunctionalProperty .
    BIND("Functional" AS ?role)
  }
  OPTIONAL {
    ?property rdf:type owl:InverseFunctionalProperty .
    BIND("Inverse Functional" AS ?role)
  }
  OPTIONAL {
    FILTER NOT EXISTS { ?property rdf:type owl:FunctionalProperty . }
    FILTER NOT EXISTS { ?property rdf:type owl:InverseFunctionalProperty . }
    BIND("Non-Functional" AS ?role)
  }
}
